#if UNITY_EDITOR
using System;
using System.Reflection;
using LastRail.Battle;
using Newtonsoft.Json.Linq;
using NUnit.Framework;
namespace LastRail.Tests.EditMode {
 public sealed class CombatEquipmentLoadoutTests {
  static Type TypeOf(string name){var t=typeof(CombatVitals).Assembly.GetType("LastRail.Battle."+name);Assert.NotNull(t,"Actual equipment/OC01 boundary missing");return t;}
  static object EnumOf(string name,string value)=>Enum.Parse(TypeOf(name),value);
  static object Item(string id,string tag)=>Activator.CreateInstance(TypeOf("CombatEquippedItem"),"op",id,tag);
  static object Load(string owner="op",string role="Operator",params string[] tags){var arr=Array.CreateInstance(TypeOf("CombatEquippedItem"),3);for(int i=0;i<tags.Length;i++)if(tags[i]!=null)arr.SetValue(Item("item"+i,tags[i]),i);return Activator.CreateInstance(TypeOf("CombatEquipmentLoadout"),owner,EnumOf("CombatEquipmentOwnerKind",role),arr);}
  static object Call(string name,params object[] args){try{return TypeOf("CombatOc01Policy").GetMethod(name).Invoke(null,args);}catch(TargetInvocationException e){throw e.InnerException;}}
  static int Bps(object load,bool active=true,string kind="OrdinaryDirect",bool allowed=true)=>(int)Call("ReductionBps",load,active,EnumOf("CombatIncomingDamageKind",kind),allowed);
  static JObject Value(string n,string d="1")=>new JObject{["numerator"]=n,["denominator"]=d};
  static JObject Budget()=>new JObject{["version"]="combat.numeric-defense-budget.v1",["base"]=Value("1000"),["defense"]=Value("250"),["effects"]=new JArray(),["weakening"]=new JArray(),["penetration"]=new JArray(),["reductions"]=new JObject{["equipment"]=new JArray(),["guardStance"]=new JArray(),["independent"]=new JArray()}};
  [TestCase("A","B","C",1000)][TestCase("A","A","B",0)][TestCase("A","A","A",0)][TestCase("A","B",null,0)][TestCase(null,null,null,0)]
  public void OnlyThreeActualDistinctTagsQualify(string a,string b,string c,int expected)=>Assert.AreEqual(expected,Bps(Load("op","Operator",a,b,c)));
  [Test] public void CountsAreActualOneTwoThreeNotVirtualMembers(){var l=Load("op","Operator","A","A","B");Assert.AreEqual(2,l.GetType().GetMethod("CountTag").Invoke(l,new object[]{"A"}));Assert.AreEqual(1,l.GetType().GetMethod("CountTag").Invoke(l,new object[]{"B"}));Assert.AreEqual(0,l.GetType().GetMethod("CountTag").Invoke(l,new object[]{"C"}));Assert.AreEqual(3,Load("op","Operator","A","A","A").GetType().GetMethod("CountTag").Invoke(Load("op","Operator","A","A","A"),new object[]{"A"}));}
  [TestCase("Turret")][TestCase("Sentry")][TestCase("Carriage")][TestCase("Train")]
  public void NonOperatorOwnersNeverReceiveOc01(string role)=>Assert.AreEqual(0,Bps(Load("op",role,"A","B","C")));
  [TestCase("FixedMechanic")][TestCase("SelfDamage")][TestCase("Failure")][TestCase("TrainTransfer")]
  public void ExcludedDamageDoesNotQualify(string kind)=>Assert.AreEqual(0,Bps(Load("op","Operator","A","B","C"),true,kind));
  [Test] public void TraitAndPipelineEligibilityAreRequired(){var l=Load("op","Operator","A","B","C");Assert.AreEqual(0,Bps(l,false));Assert.AreEqual(0,Bps(l,true,"OrdinaryDirect",false));Assert.AreEqual(1000,Bps(l,true,"OrdinaryDot"));}
  [Test] public void ExistingDefenseThenOc01ThenShieldAndHp(){var input=Budget();var original=input.DeepClone();var result=(CombatNumericDefenseResult)Call("ResolveOrdinary",input,"op",Load("op","Operator","A","B","C"),true,EnumOf("CombatIncomingDamageKind","OrdinaryDirect"),true);Assert.AreEqual(720,result.ToVitalsMagnitude());Assert.IsTrue(JToken.DeepEquals(input,original));var v=new CombatVitals(1000,4000,true);v.Shield(new CombatShieldSource("caster","shield",0),200,100,0);var hit=v.Damage(result.ToVitalsMagnitude(),0,false);Assert.AreEqual(200,hit.Absorbed);Assert.AreEqual(520,hit.HpLoss);Assert.AreEqual(480,v.Hp);}
  [Test] public void FractionalDamageIsNotFlooredBeforeOc01(){var i=Budget();i["base"]=Value("10");i["defense"]=Value("500");var r=(CombatNumericDefenseResult)Call("ResolveOrdinary",i,"op",Load("op","Operator","A","B","C"),true,EnumOf("CombatIncomingDamageKind","OrdinaryDot"),true);Assert.AreEqual(6,r.ToVitalsMagnitude());}
  [Test] public void WrongOwnerAndDoubleOc01InjectionFail(){var i=Budget();Assert.Throws<ArgumentException>(()=>Call("ResolveOrdinary",i,"other",Load("op","Operator","A","B","C"),true,EnumOf("CombatIncomingDamageKind","OrdinaryDirect"),true));((JArray)i["reductions"]["independent"]).Add(new JObject{["groupId"]="OC01",["valueBps"]=1000});Assert.Throws<ArgumentException>(()=>Call("ResolveOrdinary",i,"op",Load("op","Operator","A","B","C"),true,EnumOf("CombatIncomingDamageKind","OrdinaryDirect"),true));}
  [Test] public void MissingTagIsValidButHasNoBonus(){var arr=Array.CreateInstance(TypeOf("CombatEquippedItem"),3);arr.SetValue(Item("a",null),0);arr.SetValue(Item("b","B"),1);arr.SetValue(Item("c","C"),2);var l=Activator.CreateInstance(TypeOf("CombatEquipmentLoadout"),"op",EnumOf("CombatEquipmentOwnerKind","Operator"),arr);Assert.AreEqual(0,Bps(l));}
  static void Rejected(Action action){var ex=Assert.Throws<TargetInvocationException>(()=>action());Assert.IsInstanceOf<ArgumentException>(ex.InnerException);}
  [Test] public void EquipmentItemsMustBelongToTheSameActualOwner(){var arr=Array.CreateInstance(TypeOf("CombatEquippedItem"),3);for(int n=0;n<3;n++)arr.SetValue(Activator.CreateInstance(TypeOf("CombatEquippedItem"),n==2?"other":"op","item"+n,"ABC"[n].ToString()),n);Rejected(()=>Activator.CreateInstance(TypeOf("CombatEquipmentLoadout"),"op",EnumOf("CombatEquipmentOwnerKind","Operator"),arr));}
  [Test] public void InvalidSlotCountDuplicateInstanceAndUnknownEnumsFail(){Rejected(()=>Activator.CreateInstance(TypeOf("CombatEquipmentLoadout"),"op",EnumOf("CombatEquipmentOwnerKind","Operator"),Array.CreateInstance(TypeOf("CombatEquippedItem"),2)));var arr=Array.CreateInstance(TypeOf("CombatEquippedItem"),3);arr.SetValue(Item("same","A"),0);arr.SetValue(Item("same","B"),1);Rejected(()=>Activator.CreateInstance(TypeOf("CombatEquipmentLoadout"),"op",EnumOf("CombatEquipmentOwnerKind","Operator"),arr));Rejected(()=>Activator.CreateInstance(TypeOf("CombatEquipmentLoadout"),"op",Enum.ToObject(TypeOf("CombatEquipmentOwnerKind"),99),Array.CreateInstance(TypeOf("CombatEquippedItem"),3)));Assert.Throws<ArgumentException>(()=>Call("ReductionBps",Load("op","Operator","A","B","C"),true,Enum.ToObject(TypeOf("CombatIncomingDamageKind"),99),true));Assert.Throws<ArgumentException>(()=>Call("ResolveOrdinary",Budget(),"op",Load("op","Operator","A","B","C"),true,EnumOf("CombatIncomingDamageKind","FixedMechanic"),true));}
  [Test] public void ReplacementChangesNextHitWhileRetainedLoadoutKeepsOriginalResult(){var old=Load("op","Operator","A","B","C");var replacement=Load("op","Operator","A","A","B");var kind=EnumOf("CombatIncomingDamageKind","OrdinaryDirect");Assert.AreEqual(720,((CombatNumericDefenseResult)Call("ResolveOrdinary",Budget(),"op",old,true,kind,true)).ToVitalsMagnitude());Assert.AreEqual(800,((CombatNumericDefenseResult)Call("ResolveOrdinary",Budget(),"op",replacement,true,kind,true)).ToVitalsMagnitude());Assert.AreEqual(720,((CombatNumericDefenseResult)Call("ResolveOrdinary",Budget(),"op",old,true,kind,true)).ToVitalsMagnitude());}
  [Test] public void ExistingReductionGroupsArePreservedAndOc01MultipliesOnce(){var input=Budget();input["reductions"]["equipment"]=new JArray(new JObject{["sourceId"]="eq",["valueBps"]=1000});input["reductions"]["guardStance"]=new JArray(new JObject{["sourceId"]="guard",["valueBps"]=2000});input["reductions"]["independent"]=new JArray(new JObject{["groupId"]="other",["valueBps"]=3000});var original=input.DeepClone();var l=Load("op","Operator","A","B","C");var kind=EnumOf("CombatIncomingDamageKind","OrdinaryDirect");Assert.AreEqual(362,((CombatNumericDefenseResult)Call("ResolveOrdinary",input,"op",l,true,kind,true)).ToVitalsMagnitude());Assert.AreEqual(403,((CombatNumericDefenseResult)Call("ResolveOrdinary",input,"op",l,false,kind,true)).ToVitalsMagnitude());Assert.AreEqual(403,((CombatNumericDefenseResult)Call("ResolveOrdinary",input,"op",l,true,kind,false)).ToVitalsMagnitude());Assert.IsTrue(JToken.DeepEquals(input,original));((JArray)input["reductions"]["independent"]).Add(new JObject{["groupId"]="OC01",["valueBps"]=1000});Assert.Throws<ArgumentException>(()=>Call("ResolveOrdinary",input,"op",l,false,kind,false));}
  [Test] public void SlotCopyCannotChangeOriginalLoadout(){var arr=Array.CreateInstance(TypeOf("CombatEquippedItem"),3);arr.SetValue(Item("a","A"),0);arr.SetValue(Item("b","B"),1);arr.SetValue(Item("c","C"),2);var l=Activator.CreateInstance(TypeOf("CombatEquipmentLoadout"),"op",EnumOf("CombatEquipmentOwnerKind","Operator"),arr);arr.SetValue(null,0);Assert.AreEqual(1000,Bps(l));Assert.AreEqual(0,Bps(Load("op","Operator",null,"B","C")));}
 }
}
#endif
